PREFIX hw:   <https://trustgraph.ai/ontology/hwsec/hw#>
PREFIX sec:  <https://trustgraph.ai/ontology/hwsec/sec#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl:  <http://www.w3.org/2002/07/owl#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>

SELECT ?system ?subsystem ?component ?subcomp ?element
WHERE {
  ?system a hw:System ;
          hw:hasSubsystem ?subsystem .
  ?subsystem hw:hasComponent ?component .
  OPTIONAL { ?component hw:hasSubComponent ?subcomp .
             OPTIONAL { ?subcomp hw:hasElement ?element . }
  }
}
ORDER BY ?subsystem ?component ?subcomp ?element

PREFIX hw:   <https://trustgraph.ai/ontology/hwsec/hw#>
PREFIX sec:  <https://trustgraph.ai/ontology/hwsec/sec#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl:  <http://www.w3.org/2002/07/owl#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>

SELECT ?component ?label ?manufacturer ?arch ?package
WHERE {
  ?component a hw:Component ;
             rdfs:label ?label .
  OPTIONAL { ?component hw:manufacturer ?manufacturer . }
  OPTIONAL { ?component hw:architecture ?arch . }
  OPTIONAL { ?component hw:packageType ?package . }
}

PREFIX hw:   <https://trustgraph.ai/ontology/hwsec/hw#>
PREFIX sec:  <https://trustgraph.ai/ontology/hwsec/sec#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl:  <http://www.w3.org/2002/07/owl#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>

SELECT ?entity ?entityLabel ?vuln ?cvss ?cwe ?patchAvail
WHERE {
  ?entity hw:hasSecurityProperty ?vuln .
  ?vuln a sec:Vulnerability ;
        sec:cvssBaseScore ?cvss .
  OPTIONAL { ?entity rdfs:label ?entityLabel . }
  OPTIONAL { ?vuln sec:mapsToCWE ?cwe . }
  OPTIONAL { ?vuln sec:patchAvailable ?patchAvail . }
}
ORDER BY DESC(?cvss)

PREFIX hw:   <https://trustgraph.ai/ontology/hwsec/hw#>
PREFIX sec:  <https://trustgraph.ai/ontology/hwsec/sec#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl:  <http://www.w3.org/2002/07/owl#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>

SELECT ?entity ?entityLabel ?vuln ?cvss ?cwe
WHERE {
  ?entity hw:hasSecurityProperty ?vuln ;
          rdfs:label ?entityLabel .
  ?vuln a sec:Vulnerability ;
        sec:cvssBaseScore ?cvss .
  FILTER(?cvss >= 7.0)
  FILTER NOT EXISTS { ?vuln sec:patchAvailable true . }
}
ORDER BY DESC(?cvss)

PREFIX hw:   <https://trustgraph.ai/ontology/hwsec/hw#>
PREFIX sec:  <https://trustgraph.ai/ontology/hwsec/sec#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl:  <http://www.w3.org/2002/07/owl#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>

SELECT ?entity ?entityLabel ?vuln ?cvss
WHERE {
  ?entity hw:hasSecurityProperty ?vuln ;
          rdfs:label ?entityLabel .
  ?vuln a sec:Vulnerability ;
        sec:cvssBaseScore ?cvss .
  FILTER NOT EXISTS {
    ?cm a sec:Countermeasure ;
        sec:mitigates ?vuln .
  }
}
ORDER BY DESC(?cvss)

PREFIX hw:   <https://trustgraph.ai/ontology/hwsec/hw#>
PREFIX sec:  <https://trustgraph.ai/ontology/hwsec/sec#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl:  <http://www.w3.org/2002/07/owl#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>

SELECT ?entity ?entityLabel ?vuln ?cvss ?cve
WHERE {
  ?entity hw:hasSecurityProperty ?vuln ;
          rdfs:label ?entityLabel .
  ?vuln a sec:Vulnerability ;
        sec:exploitAvailable true ;
        sec:cvssBaseScore ?cvss .
  FILTER NOT EXISTS { ?vuln sec:patchAvailable true . }
  OPTIONAL { ?vuln sec:mapsToCVE ?cve . }
}
ORDER BY DESC(?cvss)

PREFIX hw:   <https://trustgraph.ai/ontology/hwsec/hw#>
PREFIX sec:  <https://trustgraph.ai/ontology/hwsec/sec#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl:  <http://www.w3.org/2002/07/owl#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>

SELECT ?entity ?entityLabel ?surface ?vector ?complexity
WHERE {
  ?entity hw:hasSecurityProperty ?surface ;
          rdfs:label ?entityLabel .
  ?surface a sec:AttackSurface ;
           sec:remotelyExploitable true ;
           sec:accessVector ?vector .
  OPTIONAL { ?surface sec:complexity ?complexity . }
}

PREFIX hw:   <https://trustgraph.ai/ontology/hwsec/hw#>
PREFIX sec:  <https://trustgraph.ai/ontology/hwsec/sec#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl:  <http://www.w3.org/2002/07/owl#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>

SELECT ?entity ?entityLabel ?surface ?vector ?attackTechnique
WHERE {
  ?entity hw:hasSecurityProperty ?surface ;
          rdfs:label ?entityLabel .
  ?surface a sec:AttackSurface ;
           sec:remotelyExploitable true ;
           sec:authenticated false ;
           sec:accessVector ?vector .
  OPTIONAL { ?surface sec:mapsToATTACK ?attackTechnique . }
}

PREFIX hw:   <https://trustgraph.ai/ontology/hwsec/hw#>
PREFIX sec:  <https://trustgraph.ai/ontology/hwsec/sec#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl:  <http://www.w3.org/2002/07/owl#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>

SELECT ?entity ?entityLabel ?surface ?technique ?capec
WHERE {
  ?entity hw:hasSecurityProperty ?surface ;
          rdfs:label ?entityLabel .
  ?surface a sec:AttackSurface ;
           sec:mapsToATTACK ?technique .
  OPTIONAL { ?surface sec:mapsToCAPEC ?capec . }
}

PREFIX hw:   <https://trustgraph.ai/ontology/hwsec/hw#>
PREFIX sec:  <https://trustgraph.ai/ontology/hwsec/sec#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl:  <http://www.w3.org/2002/07/owl#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>

SELECT ?entity ?entityLabel ?debug ?ifaceType ?bypass
WHERE {
  ?entity hw:hasSecurityProperty ?debug ;
          rdfs:label ?entityLabel .
  ?debug a sec:DebugAccess ;
         sec:interfaceType ?ifaceType .
  OPTIONAL { ?debug sec:bypassTechnique ?bypass . }
  FILTER(
    !BOUND(?locked) || ?locked = false ||
    BOUND(?bypass)
  )
  OPTIONAL { ?debug sec:debugIsLocked ?locked . }
}

PREFIX hw:   <https://trustgraph.ai/ontology/hwsec/hw#>
PREFIX sec:  <https://trustgraph.ai/ontology/hwsec/sec#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl:  <http://www.w3.org/2002/07/owl#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>

SELECT ?entity ?entityLabel ?iface ?protocol ?location
WHERE {
  ?entity hw:hasInterface ?iface ;
          rdfs:label ?entityLabel .
  ?iface a hw:PhysicalInterface ;
         hw:protocol ?protocol .
  OPTIONAL { ?iface hw:boardLocation ?location . }
  FILTER NOT EXISTS { ?iface hw:probeRequired true . }
}

PREFIX hw:   <https://trustgraph.ai/ontology/hwsec/hw#>
PREFIX sec:  <https://trustgraph.ai/ontology/hwsec/sec#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl:  <http://www.w3.org/2002/07/owl#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>

SELECT ?entity ?entityLabel ?boundary ?mechanism ?cve
WHERE {
  ?entity hw:hasTrustBoundary ?boundary ;
          rdfs:label ?entityLabel .
  ?boundary hw:bypassKnown true ;
            hw:boundaryMechanism ?mechanism .
  OPTIONAL { ?boundary hw:boundaryBypassCveRef ?cve . }
}

PREFIX hw:   <https://trustgraph.ai/ontology/hwsec/hw#>
PREFIX sec:  <https://trustgraph.ai/ontology/hwsec/sec#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl:  <http://www.w3.org/2002/07/owl#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>

SELECT ?entity ?iface ?protocol ?boundary ?mechanism
WHERE {
  ?entity hw:hasInterface ?iface ;
          rdfs:label ?entityLabel .
  ?iface hw:crossesTrustBoundary ?boundary ;
         hw:protocol ?protocol .
  ?boundary hw:boundaryMechanism ?mechanism .
}

PREFIX hw:   <https://trustgraph.ai/ontology/hwsec/hw#>
PREFIX sec:  <https://trustgraph.ai/ontology/hwsec/sec#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl:  <http://www.w3.org/2002/07/owl#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>

SELECT ?entity ?entityLabel ?fw ?version ?extraction
WHERE {
  ?entity hw:hasFirmware ?fw ;
          rdfs:label ?entityLabel .
  ?fw a hw:Firmware .
  FILTER NOT EXISTS { ?fw hw:isSignatureVerified true . }
  OPTIONAL { ?fw hw:firmwareBinaryVersion ?version . }
  OPTIONAL { ?fw hw:extractionMethod ?extraction . }
}

PREFIX hw:   <https://trustgraph.ai/ontology/hwsec/hw#>
PREFIX sec:  <https://trustgraph.ai/ontology/hwsec/sec#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl:  <http://www.w3.org/2002/07/owl#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>

SELECT ?entity ?entityLabel ?iface ?protocol
WHERE {
  ?entity hw:hasInterface ?iface ;
          rdfs:label ?entityLabel .
  ?iface a hw:NetworkInterface ;
         hw:remotelyReachable true ;
         hw:protocol ?protocol .
  FILTER NOT EXISTS { ?iface hw:encryptionMode ?enc . }
}

PREFIX hw:   <https://trustgraph.ai/ontology/hwsec/hw#>
PREFIX sec:  <https://trustgraph.ai/ontology/hwsec/sec#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl:  <http://www.w3.org/2002/07/owl#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>

SELECT ?entity ?entityLabel ?iface ?protocol ?range
WHERE {
  ?entity hw:hasInterface ?iface ;
          rdfs:label ?entityLabel .
  ?iface a hw:NetworkInterface ;
         hw:remotelyReachable true .
  FILTER NOT EXISTS { ?iface hw:requiresAuthentication true . }
  OPTIONAL { ?iface hw:protocol ?protocol . }
  OPTIONAL { ?iface hw:wirelessRange ?range . }
}

PREFIX hw:   <https://trustgraph.ai/ontology/hwsec/hw#>
PREFIX sec:  <https://trustgraph.ai/ontology/hwsec/sec#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl:  <http://www.w3.org/2002/07/owl#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>

SELECT ?entity ?entityLabel ?threat ?scenario ?likelihood ?impact ?vuln
WHERE {
  ?entity hw:hasSecurityProperty ?threat ;
          rdfs:label ?entityLabel .
  ?threat a sec:ThreatModel ;
          sec:threatScenario ?scenario ;
          sec:impact ?impact .
  FILTER(?impact IN ("HIGH", "CRITICAL"))
  OPTIONAL { ?threat sec:likelihood ?likelihood . }
  OPTIONAL { ?threat sec:exploits ?vuln . }
}
ORDER BY ?impact DESC(?likelihood)

PREFIX hw:   <https://trustgraph.ai/ontology/hwsec/hw#>
PREFIX sec:  <https://trustgraph.ai/ontology/hwsec/sec#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl:  <http://www.w3.org/2002/07/owl#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>

SELECT ?entity ?entityLabel ?threat ?scenario ?vuln ?cvss ?cm ?cmImplemented
WHERE {
  ?entity hw:hasSecurityProperty ?threat ;
          rdfs:label ?entityLabel .
  ?threat a sec:ThreatModel ;
          sec:threatScenario ?scenario ;
          sec:exploits ?vuln .
  ?vuln sec:cvssBaseScore ?cvss .
  OPTIONAL {
    ?cm a sec:Countermeasure ;
        sec:mitigates ?vuln ;
        sec:isImplemented ?cmImplemented .
  }
}
ORDER BY DESC(?cvss)

PREFIX hw:   <https://trustgraph.ai/ontology/hwsec/hw#>
PREFIX sec:  <https://trustgraph.ai/ontology/hwsec/sec#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl:  <http://www.w3.org/2002/07/owl#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>

SELECT ?entity ?entityLabel ?cm ?controlType ?d3fend ?effectiveness
WHERE {
  ?entity hw:hasSecurityProperty ?cm ;
          rdfs:label ?entityLabel .
  ?cm a sec:Countermeasure ;
      sec:mapsToD3FEND ?d3fend ;
      sec:controlType ?controlType .
  OPTIONAL { ?cm sec:effectiveness ?effectiveness . }
}

PREFIX hw:   <https://trustgraph.ai/ontology/hwsec/hw#>
PREFIX sec:  <https://trustgraph.ai/ontology/hwsec/sec#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl:  <http://www.w3.org/2002/07/owl#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>

SELECT ?entity ?entityLabel ?cm ?controlType ?cost ?vuln ?cvss
WHERE {
  ?entity hw:hasSecurityProperty ?cm ;
          rdfs:label ?entityLabel .
  ?cm a sec:Countermeasure ;
      sec:isImplemented false ;
      sec:controlType ?controlType .
  OPTIONAL { ?cm sec:implementationCost ?cost . }
  OPTIONAL {
    ?cm sec:mitigates ?vuln .
    ?vuln sec:cvssBaseScore ?cvss .
  }
}
ORDER BY DESC(?cvss)

PREFIX hw:   <https://trustgraph.ai/ontology/hwsec/hw#>
PREFIX sec:  <https://trustgraph.ai/ontology/hwsec/sec#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl:  <http://www.w3.org/2002/07/owl#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>

SELECT ?component ?componentLabel ?subcomp ?subcompLabel ?ipBlock
WHERE {
  ?component hw:hasSubComponent ?subcomp ;
             rdfs:label ?componentLabel .
  ?subcomp hw:isShared true ;
           rdfs:label ?subcompLabel .
  OPTIONAL { ?subcomp hw:ipBlock ?ipBlock . }
}

PREFIX hw:   <https://trustgraph.ai/ontology/hwsec/hw#>
PREFIX sec:  <https://trustgraph.ai/ontology/hwsec/sec#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl:  <http://www.w3.org/2002/07/owl#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>

SELECT ?component ?label ?manufacturer ?eol ?vuln ?cvss
WHERE {
  ?component a hw:Component ;
             rdfs:label ?label ;
             hw:endOfLife ?eol .
  FILTER(?eol < NOW())
  ?component hw:hasSecurityProperty ?vuln .
  ?vuln a sec:Vulnerability ;
        sec:cvssBaseScore ?cvss .
  OPTIONAL { ?component hw:manufacturer ?manufacturer . }
}
ORDER BY DESC(?cvss)

PREFIX hw:   <https://trustgraph.ai/ontology/hwsec/hw#>
PREFIX sec:  <https://trustgraph.ai/ontology/hwsec/sec#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl:  <http://www.w3.org/2002/07/owl#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>

SELECT ?entity ?entityLabel ?trustLevel ?iface ?protocol ?range
WHERE {
  ?entity hw:trustLevel ?trustLevel ;
          hw:hasInterface ?iface ;
          rdfs:label ?entityLabel .
  ?iface a hw:NetworkInterface ;
         hw:remotelyReachable true ;
         hw:protocol ?protocol .
  FILTER(?trustLevel <= 1)
  OPTIONAL { ?iface hw:wirelessRange ?range . }
}
